fn contains_consecutive_numbers(a: &[i32]) -> bool {
    // Iterate over all adjacent pairs using `windows(2)`.
    // For each window of two elements [x, y], check if y == x + 1.
    a.windows(2).any(|w| w[0] + 1 == w[1])
}

